import WarningIcon from '@jetbrains/icons/warning.svg'
import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {baseUri} from '@jetbrains/teamcity-ui'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'
import {skipToken} from '@reduxjs/toolkit/query'
import {useMemo} from 'react'

import BuildLineLayout from '../../../../../containers/BuildLineLayout'
import {getSingleAgentArg} from '../../../../../rest/agents'
import {getSingleBuildArg} from '../../../../../rest/builds'
import {getBuildLocator} from '../../../../../rest/locators'
import {getAgentPoolHref, getAgentTypeHref} from '../../../../../routes'
import {getBuild} from '../../../../../selectors'
import {restApi} from '../../../../../services/rest'
import type {NormalizedAgent, NormalizedCloudImage} from '../../../../../types'
import {stringifyId} from '../../../../../types'
import BuildsWrapped, {BuildsWrappedPlaceholder} from '../../../../common/Builds/Builds.wrapped'
import CopyIconButton from '../../../../common/CopyIconButton/CopyIconButton'
import Icon from '../../../../common/Icon/Icon'
import InjectHtml from '../../../../common/InjectHtml/InjectHtml'
import LinkWithIcon from '../../../../common/LinkWithIcon/LinkWithIcon'
import RouterLinkWrapper from '../../../../common/RouterLinkWrapper/RouterLinkWrapper'
import {isCloudImageManageable} from '../../AgentsPages.utils'
import {agentPageOptions} from '../AgentPage.rest'

import styles from './AgentSummary.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  agent: NormalizedAgent
  cloudImage: NormalizedCloudImage | null | undefined
  className?: string
}

const UNKNOWN_VERSION = 'unknown'

function AgentSummary({agent, cloudImage, className}: Props) {
  const {host, port, cpuRank} = restApi.endpoints.getAgentNormalized.useQuery(
    getSingleAgentArg(agent.id, agentPageOptions),
    {
      selectFromResult: ({data}) => {
        const {host, port, cpuRank} = data?.details ?? {}
        return {host, port, cpuRank}
      },
    },
  )

  const hasBuild = 'build' in agent
  const buildId = agent.build
  const isBuildLoaded = useAppSelector(state => getBuild(state, buildId) != null)
  restApi.endpoints.getBuildNormalized.useQuerySubscription(
    buildId != null ? getSingleBuildArg(getBuildLocator(buildId)) : skipToken,
  )
  const build = useMemo(
    () =>
      hasBuild ? (
        <BuildLineLayout showAgent={false} showExactDuration={false} showPath showBranch>
          <H2 className={styles.runningBuildHeading}>{'Running build'}</H2>
          {buildId != null ? (
            isBuildLoaded ? (
              <BuildsWrapped buildIds={[buildId]} />
            ) : (
              <BuildsWrappedPlaceholder />
            )
          ) : (
            <div className={styles.runningBuildPlaceholder}>
              <Icon className={styles.runningIcon} name="running_green" />
              {'You do not have permissions to see the build details.'}
            </div>
          )}
        </BuildLineLayout>
      ) : null,
    [buildId, hasBuild, isBuildLoaded],
  )

  return (
    <div className={className}>
      {agent.pool != null ? (
        <>
          <div className={styles.row} data-agent-summary-row>
            <div className={styles.rowTitle}>{'Agent pool'}</div>
            <RouterLinkWrapper>
              <Link href={getAgentPoolHref(agent.pool.id)}>{agent.pool.name}</Link>
            </RouterLinkWrapper>
          </div>
        </>
      ) : null}
      {cloudImage != null ? (
        <>
          <div className={styles.row} data-agent-summary-row>
            <div className={styles.rowTitle}>{'Cloud image'}</div>
            <RouterLinkWrapper>
              <Link href={getAgentTypeHref(cloudImage.agentTypeId)}>{cloudImage.name}</Link>
            </RouterLinkWrapper>
          </div>
          {cloudImage.profile != null ? (
            <div className={styles.row} data-agent-summary-row>
              <div className={styles.rowTitle}>{'Cloud profile'}</div>
              <div>
                {cloudImage.profile.name}
                {isCloudImageManageable(cloudImage) && (
                  <LinkWithIcon
                    href={`${baseUri}/admin/editProject.html?projectId=${stringifyId(
                      cloudImage.profile.projectId,
                    )}&tab=clouds&action=edit&profileId=${stringifyId(
                      cloudImage.profile?.id,
                    )}&showEditor=true`}
                    className={styles.editLink}
                    icon="pencil"
                    iconClassName={styles.editIcon}
                  >
                    {'Edit'}
                  </LinkWithIcon>
                )}
              </div>
            </div>
          ) : null}
        </>
      ) : null}
      <div className={styles.row} data-agent-summary-row>
        <div className={styles.rowTitle}>{'Hostname'}</div>
        <div>
          {host}
          <CopyIconButton
            text={host}
            iconClassName={styles.copyButton}
            title={'Copy hostname to clipboard'}
          />
        </div>
      </div>
      {agent.ip !== host ? (
        <div className={styles.row} data-agent-summary-row>
          <div className={styles.rowTitle}>{'IP'}</div>
          <div>
            {agent.ip}
            <CopyIconButton
              text={agent.ip}
              iconClassName={styles.copyButton}
              title={'Copy IP to clipboard'}
            />
          </div>
        </div>
      ) : null}
      <div className={styles.row} data-agent-summary-row>
        <div className={styles.rowTitle}>{'Port'}</div>
        <div>{port}</div>
      </div>
      <div className={styles.row} data-agent-summary-row>
        <div className={styles.rowTitle}>{'Operating system'}</div>
        <div>{agent.osName}</div>
      </div>
      <div className={styles.row} data-agent-summary-row>
        <div className={styles.rowTitle}>{'CPU rank'}</div>
        <div>{cpuRank}</div>
      </div>
      {agent.version !== UNKNOWN_VERSION ? (
        <div className={styles.row} data-agent-summary-row>
          <div className={styles.rowTitle}>
            {agent.outdated === true || agent.pluginsOutdated === true ? (
              <>
                <SvgIcon className={styles.warinigIcon} icon={WarningIcon} />{' '}
              </>
            ) : null}
            {'Version'}
          </div>
          <div>
            {agent.version}
            {agent.outdated === true &&
            agent.currentAgentVersion != null &&
            agent.currentAgentVersion !== UNKNOWN_VERSION ? (
              <>
                {' (outdated, current version is '}
                <strong>{agent.currentAgentVersion}</strong>
                {')'}
              </>
            ) : null}
            {agent.outdated !== true && agent.pluginsOutdated === true
              ? ' (some plugins on the agent are out of date)'
              : null}
          </div>
        </div>
      ) : null}
      {agent.javaOutdated === true ? (
        <div className={styles.warningRow}>
          <SvgIcon className={styles.warinigIcon} icon={WarningIcon} />
          {
            " This agent can't be upgraded automatically since it is running under an unsupported JRE. Java versions 8 and later are supported."
          }
        </div>
      ) : null}
      {build}
      <InjectHtml
        className={styles.plugins}
        path={`agentDetails.html?${objectToQuery({
          id: stringifyId(agent.id),
          tab: 'agentSummary',
          __fragmentId: 'agentSummaryExtensionsInner',
        })}#${JSON.stringify({
          enabled: agent.enabled,
          authorized: agent.authorized,
          connected: agent.connected,
        })}`}
      />
    </div>
  )
}

export default AgentSummary
