import {CustomItem} from '@jetbrains/ring-ui-built/components/tabs/dumb-tabs'
import {Tabs} from '@jetbrains/ring-ui-built/components/tabs/tabs'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import * as React from 'react'
import {Suspense} from 'react'
import {EntryPointContainer, type PreloadedQuery} from 'react-relay'
import type {PreloadedEntryPoint} from 'react-relay/relay-hooks/EntryPointTypes'
import {useNavigate} from 'react-router'

import AgentHistory from '../../../../containers/AgentHistory'
import {useQueryParam} from '../../../../hooks/routes'
import useDocumentTitle from '../../../../hooks/useDocumentTitle'
import {getTabsArg} from '../../../../rest/tabs'
import {getAgentHref, getAgentPoolHref} from '../../../../routes'
import {restApi} from '../../../../services/rest'
import type {AgentId, NormalizedAgent, NormalizedCloudImage, TabId} from '../../../../types'
import {
  ClassicUIAgentTabNamesEnum,
  OverviewAgentTabNamesEnum,
  stringifyId,
  toTabId,
} from '../../../../types'
import {internalProps} from '../../../../types/BS_types'
import {emptyArray} from '../../../../utils/empty'
import {getTabParamsKey} from '../../../../utils/tabs'
import {osIconMap} from '../../../common/AgentLink/AgentLink'
import ClassicUITabAdapter from '../../../common/ClassicUITabAdapter/ClassicUITabAdapter'
import Loader from '../../../common/Loader/Loader'
import OverviewTab from '../../../common/OverviewTab/OverviewTab'
import PageTitle from '../../../common/PageTitle/PageTitle'
import Plugin from '../../../common/Plugin/Plugin'
import TabsLoader from '../../../common/TabsLoader/TabsLoader'
import type {AgentsPagesPoolsAuthorizePermissionsQuery} from '../__generated__/AgentsPagesPoolsAuthorizePermissionsQuery.graphql'
import {isCloudImageManageable} from '../AgentsPages.utils'
import type {AuthorizeAgentLicensingDataQuery} from '../components/AgentListView/AuthorizeAgent/__generated__/AuthorizeAgentLicensingDataQuery.graphql'
import {
  AuthorizeAgentContainer,
  UnauthorizeAgentContainer,
} from '../components/AgentListView/AuthorizeAgent/AuthorizeAgent'

import {useCanStopBuild} from './AgentPage.hooks'
import {getMappedTabs} from './AgentPage.utils'
import type {AgentParametersComponentType} from './AgentParameters/AgentParameters'
import AgentConnectionStatus from './AgentStatus/AgentConnectionStatus'
import AgentEnableAuthStatus from './AgentStatus/AgentEnableAuthStatus'
import AgentSummary from './AgentSummary/AgentSummary'
import DeletedAgent from './DeletedAgent/DeletedAgent'
import EnableAgent from './EnableAgent/EnableAgent'
import RemoveAgent from './RemoveAgentButton/RemoveAgentButton'
import StopInstance from './StopInstanceButton/StopInstanceButton'

import styles from './AgentPage.module.css'

import useEventCallback from 'src/hooks/useEventCallback'

const AgentBuildTypesLazy = React.lazy(
  () =>
    import(
      /* webpackChunkName: "AgentBuildTypes" */
      './AgentBuildTypes/AgentBuildTypes'
    ),
)
type Props = {
  agentId: AgentId
  agent: NormalizedAgent | null | undefined
  cloudImage: NormalizedCloudImage | null | undefined
  ready: boolean
  isAutodetectTimeZone?: boolean
  parametersTabEntryPoint?: PreloadedEntryPoint<AgentParametersComponentType>
  onSelect: (arg0: string) => void
  poolsAuthorizePermissionsQueryRef: PreloadedQuery<AgentsPagesPoolsAuthorizePermissionsQuery>
  licensingDataQueryRef: PreloadedQuery<AuthorizeAgentLicensingDataQuery>
}

function AgentActions({
  agent,
  cloudImage,
  poolsAuthorizePermissionsQueryRef,
  licensingDataQueryRef,
}: {
  agent: NormalizedAgent
  cloudImage: NormalizedCloudImage | null | undefined
  poolsAuthorizePermissionsQueryRef: PreloadedQuery<AgentsPagesPoolsAuthorizePermissionsQuery>
  licensingDataQueryRef: PreloadedQuery<AuthorizeAgentLicensingDataQuery>
}) {
  const canStopBuild = useCanStopBuild(agent.build)
  const {isToggleable} = restApi.endpoints.getPoolPermissions.useQuery(undefined, {
    selectFromResult: ({data}) => ({
      isToggleable: agent.pool.id != null && data?.[agent.pool.id]?.canChangeStatus,
    }),
  })
  const isImageManageable = isCloudImageManageable(cloudImage)
  const navigate = useNavigate()
  const onRemove = useEventCallback(() => {
    navigate(getAgentPoolHref(agent.pool.id))
  })

  return (
    <div>
      {(cloudImage == null || isImageManageable) && (
        <>
          {isToggleable && <EnableAgent agent={agent} className={styles.action} />}
          {agent.authorized ? (
            <UnauthorizeAgentContainer
              className={styles.action}
              id={agent.id}
              name={agent.name}
              poolId={agent.pool.id}
            />
          ) : (
            <AuthorizeAgentContainer
              className={styles.action}
              id={agent.id}
              name={agent.name}
              poolId={agent.pool.id}
              poolsAuthorizePermissionsQueryRef={poolsAuthorizePermissionsQueryRef}
              licensingDataQueryRef={licensingDataQueryRef}
            />
          )}
          {agent.cloudInstanceId == null || (agent.build != null && !canStopBuild) ? null : (
            <StopInstance
              className={styles.action}
              cloudInstanceId={agent.cloudInstanceId}
              agentTypeId={agent.typeId}
            />
          )}
          {agent.connected || (agent.build != null && !canStopBuild) ? null : (
            <RemoveAgent className={styles.action} agent={agent} onRemove={onRemove} />
          )}
        </>
      )}
      <Plugin placeId={PlaceId.SAKURA_AGENT_ACTIONS} inline />
    </div>
  )
}

export default function AgentPage({
  agentId,
  onSelect,
  agent,
  cloudImage,
  ready,
  isAutodetectTimeZone = false,
  parametersTabEntryPoint,
  poolsAuthorizePermissionsQueryRef,
  licensingDataQueryRef,
}: Props) {
  useDocumentTitle(agent && `Agent Summary (${agent.name}) — TeamCity`)

  const kind = useQueryParam('kind')
  const tabParam = useQueryParam('tab')
  const tabParamsKey = getTabParamsKey({
    agentId,
  })
  const {tabsReady, fetchedTabs} = restApi.endpoints.getTabs.useQuery(getTabsArg(tabParamsKey), {
    selectFromResult: ({data}) => ({tabsReady: data != null, fetchedTabs: data ?? emptyArray}),
  })
  const tabs = getMappedTabs(fetchedTabs)
  const tab = tabParam != null ? toTabId(tabParam) : OverviewAgentTabNamesEnum.SUMMARY

  if (!ready) {
    return <Loader />
  }

  if (agent == null) {
    return null
  }

  const {authorizedInfo, enabledInfo} = agent
  const isCloud = agent.cloudInstanceId != null
  const osIconName = `${(agent.osType != null && osIconMap[agent.osType]) || 'unknown-os'}-20px`
  return (
    <div className={styles.page}>
      <PageTitle
        className={classNames(styles.title, {
          [styles.disconnectedTitle]: !agent.connected,
          [styles.disabledTitle]: !agent.enabled,
        })}
      >
        <SvgIcon icon={osIconName} data-test-sidebar-agent={'os-icon'} /> {agent.name}
      </PageTitle>
      {agent.deleted ? (
        <DeletedAgent />
      ) : (
        <>
          <div className={styles.status}>
            <AgentConnectionStatus agent={agent} isAutodetectTimeZone={isAutodetectTimeZone} />
            {authorizedInfo != null && enabledInfo != null ? (
              <AgentEnableAuthStatus
                authorizedInfo={authorizedInfo}
                enabledInfo={enabledInfo}
                isAutodetectTimeZone={isAutodetectTimeZone}
                isCloud={isCloud}
              />
            ) : null}
          </div>
          {agent.pool != null ? (
            <Suspense>
              <AgentActions
                agent={agent}
                cloudImage={cloudImage}
                poolsAuthorizePermissionsQueryRef={poolsAuthorizePermissionsQueryRef}
                licensingDataQueryRef={licensingDataQueryRef}
              />
            </Suspense>
          ) : null}
          <Tabs
            className={styles.tabs}
            selected={tab}
            onSelect={onSelect}
            initialVisibleItems={3}
            autoCollapse={process.env.NODE_ENV !== 'test'}
          >
            {tabs.map(({id, title}) => {
              const tabId = ClassicUIAgentTabNamesEnum[id] || (toTabId(id) as TabId)
              const tabHref = `${getAgentHref(agentId)}?${objectToQuery({
                tab: stringifyId(tabId),
              })}`

              if (tabId === OverviewAgentTabNamesEnum.SUMMARY) {
                return (
                  <OverviewTab
                    id={tabId}
                    key={stringifyId(tabId)}
                    title={<span data-test-tabid={tabId}>{title}</span>}
                    href={tabHref}
                  >
                    <AgentSummary agent={agent} cloudImage={cloudImage} />
                  </OverviewTab>
                )
              }

              if (
                tabId === OverviewAgentTabNamesEnum.COMPATIBLE_CONFIGUTATIONS &&
                internalProps['teamcity.ui.newAgentCompatibleConfigurationsTab']
              ) {
                return (
                  <OverviewTab id={tabId} key={stringifyId(tabId)} title={title} href={tabHref}>
                    <AgentBuildTypesLazy />
                  </OverviewTab>
                )
              }

              if (tabId === OverviewAgentTabNamesEnum.PARAMETERS) {
                return (
                  <OverviewTab id={tabId} key={stringifyId(tabId)} title={title} href={tabHref}>
                    {parametersTabEntryPoint && (
                      <Suspense>
                        <EntryPointContainer
                          entryPointReference={parametersTabEntryPoint}
                          props={{}}
                        />
                      </Suspense>
                    )}
                  </OverviewTab>
                )
              }

              if (tabId === OverviewAgentTabNamesEnum.HISTORY) {
                return (
                  <OverviewTab id={tabId} key={stringifyId(tabId)} title={title} href={tabHref}>
                    <AgentHistory
                      agent={{
                        id: agent.id,
                      }}
                    />
                  </OverviewTab>
                )
              }

              return tabId != null ? (
                <OverviewTab
                  isClassic
                  id={tabId}
                  key={stringifyId(tabId)}
                  title={title}
                  href={tabHref}
                >
                  <ClassicUITabAdapter agentId={agent.id} tabId={id} title={title} kind={kind} />
                </OverviewTab>
              ) : null
            })}
            {!tabsReady ? (
              <CustomItem key="tabs_loader">
                <TabsLoader />
              </CustomItem>
            ) : null}
          </Tabs>
        </>
      )}
    </div>
  )
}
