import Button from '@jetbrains/ring-ui-built/components/button/button'
import Confirm from '@jetbrains/ring-ui-built/components/confirm/confirm'
import * as React from 'react'
import {useCallback, useState} from 'react'
import {graphql, useMutation} from 'react-relay'
import {useNavigate} from 'react-router'

import {getAgentTypeHref} from '../../../../../routes'
import type {AgentTypeId, CloudInstanceId} from '../../../../../types'
import {stringifyId} from '../../../../../types'
import escapeLocatorDimension from '../../../../../utils/escapeLocatorDimension'

import type {StopInstanceButtonMutation} from './__generated__/StopInstanceButtonMutation.graphql'

const mutation = graphql`
  mutation StopInstanceButtonMutation($instanceLocator: String!) {
    stopInstance(instanceLocator: $instanceLocator)
  }
`

function StopInstanceButton({
  className,
  cloudInstanceId,
  agentTypeId,
}: {
  className?: string
  cloudInstanceId: CloudInstanceId
  agentTypeId: AgentTypeId
}) {
  const navigate = useNavigate()
  const [showStopConfirm, setShowStopConfirm] = useState(false)
  const onClickStop = useCallback(() => {
    setShowStopConfirm(true)
  }, [])
  const [stopCloudInstance] = useMutation<StopInstanceButtonMutation>(mutation)
  const onConfirmStopInstance = useCallback(() => {
    setShowStopConfirm(false)
    stopCloudInstance({
      variables: {instanceLocator: `id:${escapeLocatorDimension(stringifyId(cloudInstanceId))}`},
      onCompleted: () => {
        navigate(getAgentTypeHref(agentTypeId))
      },
    })
  }, [stopCloudInstance, agentTypeId, cloudInstanceId, navigate])
  const onRejectRemoveAgent = useCallback(() => {
    setShowStopConfirm(false)
  }, [])

  return (
    <>
      <Button className={className} onClick={onClickStop}>
        {'Stop'}
      </Button>
      <Confirm
        text="Stop this agent?"
        confirmLabel="Yes"
        rejectLabel="Cancel"
        show={showStopConfirm}
        onConfirm={onConfirmStopInstance}
        onReject={onRejectRemoveAgent}
      />
    </>
  )
}

export default React.memo(StopInstanceButton)
