import {getSingleAgentArg} from '../../../../../rest/agents'
import {restApi} from '../../../../../services/rest'
import type {NormalizedAgent} from '../../../../../types'
import {displayDate} from '../../../../../utils/dateTimeUtils'
import {agentPageOptions} from '../AgentPage.rest'

import styles from './AgentStatus.module.css'

type Props = {
  agent: NormalizedAgent
  isAutodetectTimeZone: boolean
}

function AgentConnectionStatus({agent, isAutodetectTimeZone}: Props) {
  const {id, connected, disconnectionComment, lastActivityTime} = agent
  const {connectedSince} = restApi.endpoints.getAgentNormalized.useQuery(
    getSingleAgentArg(id, agentPageOptions),
    {
      selectFromResult: ({data}) => ({
        connectedSince: data?.details.connectedSince,
      }),
    },
  )
  return (
    <div className={styles.line} data-test-agent-connection-status>
      {connected ? (
        <span className={styles.statusUp}>
          {'Connected'}
          {connectedSince != null
            ? ` since ${displayDate(connectedSince, isAutodetectTimeZone, true)}`
            : null}
        </span>
      ) : (
        <span className={styles.statusDown}>
          {'Disconnected'}
          {disconnectionComment != null ? ` — ${disconnectionComment}` : ''}
        </span>
      )}
      {lastActivityTime != null
        ? ` Last communication on ${displayDate(lastActivityTime, isAutodetectTimeZone, true)}`
        : null}
    </div>
  )
}

export default AgentConnectionStatus
