import type {Tab} from '../../../../types'
import {stringifyId} from '../../../../types'

export const getMappedTabs = (tabs: readonly Tab[]) =>
  tabs.map(tab => {
    const {id, title, ...rest} = tab

    if (stringifyId(id) === 'agentLogs') {
      return {
        id,
        title: 'Logs',
        ...rest,
      }
    }

    if (stringifyId(id) === 'agentParameters') {
      return {
        id,
        title: 'Parameters',
        ...rest,
      }
    }

    return tab
  })
