import {useEffect} from 'react'
import type {PreloadedQuery} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'
import {createSelector} from 'reselect'

import {useRefetchablePreloadedQuery} from '../../../../../../hooks/relay/useRefetchablePreloadedQuery'
import type {AgentPool} from '../../../../../../services/rest'
import type {AgentPoolId} from '../../../../../../types'
import {stringifyId, toAgentPoolId} from '../../../../../../types'
import {emptyArray} from '../../../../../../utils/empty'
import {getTopics, subscribeOnOverallEvents} from '../../../../../../utils/subscriber'
import * as SubscriptionEvents from '../../../../../../utils/subscriptionEvents'
import type {
  AgentsPagesPoolsAuthorizePermissionsQuery,
  AgentsPagesPoolsAuthorizePermissionsQuery$data,
} from '../../../__generated__/AgentsPagesPoolsAuthorizePermissionsQuery.graphql'
import {DEFAULT_AGENT_POOL_ID} from '../../../AgentPoolPage/AgentPoolPage.consts'
import {poolsAuthorizePermissionsQuery} from '../../../AgentsPages.queries'

import type {AuthorizeAgentLicensingDataQuery} from './__generated__/AuthorizeAgentLicensingDataQuery.graphql'
import {licensingDataQuery} from './AuthorizeAgent.queries'

const reducePoolsAuthorizePermissionsResponse = createSelector(
  (response: AgentsPagesPoolsAuthorizePermissionsQuery$data) => response,
  (_: AgentsPagesPoolsAuthorizePermissionsQuery$data, currentPoolId?: AgentPoolId) => currentPoolId,
  function reducePoolsAuthorizePermissionsResponse(
    {agentPools}: AgentsPagesPoolsAuthorizePermissionsQuery$data,
    currentPoolId?: AgentPoolId,
  ): ReadonlyArray<AgentPool> {
    if (agentPools == null) {
      return emptyArray
    }

    const stringCurrentPoolId = stringifyId(currentPoolId)
    let currentPoolNode = null
    const allowedPools = [] as Array<AgentPool>

    for (let i = 0; i < agentPools.edges.length; i++) {
      const node = agentPools.edges[i].node
      if (node.rawId === stringCurrentPoolId) {
        currentPoolNode = node

        if (node.permissions?.authorizeAgents) {
          // For the pool agent belongs to, it's enough to have `authorizeAgents` permission.
          allowedPools.push({id: toAgentPoolId(node.rawId), name: node.name} as AgentPool)
        }
      } else if (node.permissions?.manageAgents && node.permissions.authorizeAgents) {
        // For the pools the agent does not belong to, both `manageAgents` and `authorizeAgents` permissions are requires.
        // This is because before we authorize it, it has to be moved to the target pool.
        allowedPools.push({id: toAgentPoolId(node.rawId), name: node.name} as AgentPool)
      }
    }

    if (
      currentPoolNode == null ||
      currentPoolId === DEFAULT_AGENT_POOL_ID ||
      currentPoolNode?.permissions?.manageAgents
    ) {
      return allowedPools
    }

    if (currentPoolNode?.permissions?.authorizeAgents) {
      return [{id: toAgentPoolId(currentPoolNode.rawId), name: currentPoolNode.name} as AgentPool]
    }

    return emptyArray
  },
)

const REMAINING_AGENTS_TIMEOUT = 1000
const REMAINING_AGENT_EVENT_TYPE_TOPICS = getTopics('', [
  SubscriptionEvents.AGENT_REGISTERED,
  SubscriptionEvents.AGENT_UNREGISTERED,
  SubscriptionEvents.AGENT_STATUS_CHANGED,
  SubscriptionEvents.AGENT_REMOVED,
])

export function useAgentsLeft(queryRef: PreloadedQuery<AuthorizeAgentLicensingDataQuery>) {
  const [{licensingData}, refetch] = useRefetchablePreloadedQuery(licensingDataQuery, queryRef)
  useEffect(
    () =>
      IS_STORYBOOK
        ? undefined
        : subscribeOnOverallEvents(
            REMAINING_AGENT_EVENT_TYPE_TOPICS,
            () => refetch(queryRef.variables),
            REMAINING_AGENTS_TIMEOUT,
          ),
    [queryRef.variables, refetch],
  )
  return licensingData?.agentsLeft
}

export function useCanAuthorizeInPools(
  poolsAuthorizePermissionsQueryRef: PreloadedQuery<AgentsPagesPoolsAuthorizePermissionsQuery>,
  licensingDataQueryRef: PreloadedQuery<AuthorizeAgentLicensingDataQuery>,
  currentPoolId?: AgentPoolId,
): {isAgentLeft: boolean; canAuthorizeInPools: ReadonlyArray<AgentPool>} {
  const agentsLeft = useAgentsLeft(licensingDataQueryRef)
  const isAgentLeft = agentsLeft === -1 || (agentsLeft != null && agentsLeft > 0)
  const poolsAuthorizePermissionsResponse: AgentsPagesPoolsAuthorizePermissionsQuery$data =
    usePreloadedQuery(poolsAuthorizePermissionsQuery, poolsAuthorizePermissionsQueryRef)

  const canAuthorizeInPools = reducePoolsAuthorizePermissionsResponse(
    poolsAuthorizePermissionsResponse,
    currentPoolId,
  )

  return {isAgentLeft, canAuthorizeInPools}
}
