import {HTTPError, HTTPCodesEnum} from '@jetbrains/teamcity-ui/dist/services'
import * as React from 'react'
import type {EntryPointProps, PreloadedQuery} from 'react-relay'
import type {PreloadedEntryPoint} from 'react-relay/relay-hooks/EntryPointTypes'
import {useLocation, useNavigate, useParams} from 'react-router'

import {removeAgent} from '../../../../actions/fetch'
import {useIsAutodetectTimeZone} from '../../../../hooks/useIsAutodetectTimeZone'
import {getSingleAgentArg} from '../../../../rest/agents'
import {getHrefWithQueryParams} from '../../../../routes'
import {getSingleAgent, getSingleCloudImage} from '../../../../selectors'
import {restApi} from '../../../../services/rest'
import {toAgentId} from '../../../../types'
import type {AgentId} from '../../../../types'
import {extractError} from '../../../../utils/extractError'
import {getAvailabilityErrorMessage} from '../../../../utils/getAvailabilityErrorMessage'
import type {AgentsPagesPoolsAuthorizePermissionsQuery} from '../__generated__/AgentsPagesPoolsAuthorizePermissionsQuery.graphql'
import {AgentPagePoolsSubscriber} from '../AgentPagePoolsProvider'
import {useSubscribeOnAgentRemoval} from '../AgentsPages.hooks'
import type {AgentsPagesQueries} from '../AgentsPages.queries'
import type {AuthorizeAgentLicensingDataQuery} from '../components/AgentListView/AuthorizeAgent/__generated__/AuthorizeAgentLicensingDataQuery.graphql'

import AgentPage from './AgentPage'
import {useAgentTypeIdQueryParamEffect} from './AgentPage.hooks'
import {agentPageOptions} from './AgentPage.rest'
import type {AgentParametersComponentType} from './AgentParameters/AgentParameters'
import type {AgentParametersEntryPoint} from './AgentParameters/AgentParameters.entryPoint'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

type OwnProps = {
  agentId: AgentId
  parametersTabEntryPoint?: PreloadedEntryPoint<AgentParametersComponentType>
  poolsAuthorizePermissionsQueryRef: PreloadedQuery<AgentsPagesPoolsAuthorizePermissionsQuery>
  licensingDataQueryRef: PreloadedQuery<AuthorizeAgentLicensingDataQuery>
}

function AgentPageInnerContainer({
  agentId,
  parametersTabEntryPoint,
  poolsAuthorizePermissionsQueryRef,
  licensingDataQueryRef,
}: OwnProps) {
  const location = useLocation()
  const navigate = useNavigate()
  const {routeAvailabilityError} = restApi.endpoints.getRouteAvailability.useQueryState(
    location.pathname,
    {
      selectFromResult: ({data}) => ({
        routeAvailabilityError: data != null && data.statusCode !== HTTPCodesEnum.OK ? data : null,
      }),
    },
  )

  const agent = useAppSelector(state => getSingleAgent(state, agentId))
  const cloudImage = useAppSelector(state =>
    agent != null ? getSingleCloudImage(state, agent.typeId) : null,
  )
  const {agentReady, agentError} = restApi.endpoints.getAgentNormalized.useQuery(
    getSingleAgentArg(agentId, agentPageOptions),
    {
      selectFromResult: ({data, error}) => ({
        agentReady: data != null,
        agentError: error,
      }),
    },
  )

  const error =
    (routeAvailabilityError != null
      ? new HTTPError(
          getAvailabilityErrorMessage({error: routeAvailabilityError, agentId}) ??
            routeAvailabilityError.message,
          routeAvailabilityError.statusCode,
        )
      : null) ?? extractError(agentError)

  const isAutodetectTimeZone = useIsAutodetectTimeZone()
  const dispatch = useAppDispatch()

  useSubscribeOnAgentRemoval(agentId, true)
  React.useEffect(
    () => () => {
      if (agent?.deleted) {
        dispatch(removeAgent(agentId))
      }
    },
    [agentId, agent, dispatch],
  )

  useAgentTypeIdQueryParamEffect(agentId)

  if (!window.GLOBAL_ERROR_PAGE_DISABLED && error != null) {
    throw error
  }

  return (
    <AgentPage
      agentId={agentId}
      agent={agent}
      cloudImage={cloudImage}
      ready={agentReady}
      isAutodetectTimeZone={isAutodetectTimeZone}
      parametersTabEntryPoint={parametersTabEntryPoint}
      onSelect={tab =>
        navigate(
          getHrefWithQueryParams(location, null, () => ({
            tab,
          })),
          {preventScrollReset: true},
        )
      }
      poolsAuthorizePermissionsQueryRef={poolsAuthorizePermissionsQueryRef}
      licensingDataQueryRef={licensingDataQueryRef}
    />
  )
}

type Params = {
  agentId: string
}

type Queries = AgentsPagesQueries & {
  poolsAuthorizePermission: AgentsPagesPoolsAuthorizePermissionsQuery
  licensingData: AuthorizeAgentLicensingDataQuery
}
export type EntryPoints = {parametersTab?: typeof AgentParametersEntryPoint}

export default function AgentPageContainer({
  queries,
  entryPoints,
}: EntryPointProps<Queries, EntryPoints, {}, {}>) {
  const params = useParams<Params>()
  const agentId = toAgentId(params.agentId ?? '')

  return (
    <AgentPagePoolsSubscriber agentTypesQueryRef={queries.agentTypes}>
      <AgentPageInnerContainer
        key={params.agentId}
        agentId={agentId}
        parametersTabEntryPoint={entryPoints.parametersTab}
        poolsAuthorizePermissionsQueryRef={queries.poolsAuthorizePermission}
        licensingDataQueryRef={queries.licensingData}
      />
    </AgentPagePoolsSubscriber>
  )
}
export type AgentPageContainerComponent = typeof AgentPageContainer
