import Link from '@jetbrains/ring-ui-built/components/link/link'
import * as React from 'react'

import {useQueryParams} from '../../../../../hooks/routes'
import {getAgentTypeHref} from '../../../../../routes'
import {toAgentTypeId} from '../../../../../types'
import RouterLinkWrapper from '../../../../common/RouterLinkWrapper/RouterLinkWrapper'
import styles from '../AgentPage.module.css'

function DeletedAgent() {
  const queryParams = useQueryParams()

  return (
    <>
      <div className={styles.goneMessage}>{'This agent is no longer available.'}</div>
      {queryParams.agentTypeId && (
        <RouterLinkWrapper>
          <Link href={getAgentTypeHref(toAgentTypeId(queryParams.agentTypeId))}>
            {'Go to Cloud image'}
          </Link>
        </RouterLinkWrapper>
      )}
    </>
  )
}

export default React.memo(DeletedAgent)
